import{_ as o,W as p,s as d,u as r,ah as i,I as s,Z as l,A as n,w as a}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const k=JSON.parse('{"title":"如何在 Fedora Linux 中安装多媒体编码器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora Linux 中安装多媒体编码器 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Fedora Linux 中安装多媒体编码器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora Linux 中安装多媒体编码器 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220514 How To Install Multimedia Codecs In Fedora Linux","title":"如何在 Fedora Linux 中安装多媒体编码器","tag":"202205"},"relativePath":"202205/20220514 How To Install Multimedia Codecs In Fedora Linux.md","filePath":"[post].md"}'),u={name:"202205/20220514 How To Install Multimedia Codecs In Fedora Linux.md"};function g(m,e,h,b,f,x){const t=p("Link");return r(),d("div",null,[e[22]||(e[22]=i('<h1 id="如何在-fedora-linux-中安装多媒体编码器" tabindex="-1">如何在 Fedora Linux 中安装多媒体编码器 <a class="header-anchor" href="#如何在-fedora-linux-中安装多媒体编码器" aria-label="Permalink to 如何在 Fedora Linux 中安装多媒体编码器">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/27/112826w7kyg5vddudxwwdg.jpg" alt=""></p><blockquote><p>在新安装 Fedora后，安装多媒体编码器来播放音频和视频是第一件要事。</p></blockquote><p>在这篇简单的教程中，我们将看到如何在 Fedora 36 工作站中从 RPM Fusion 软件包存储库安装多媒体编码器。</p><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to 介绍">​</a></h3><p>很多多媒体编码器要么是闭源的，要么是非自由的，因此出于法律的原因，它们没有包含在 Fedora Linux 的默认存储库中。</p><p>幸运的是，一些第三方存储库提供了受限的和非自由的多媒体编码器、软件包和库。一个流行的社区驱动的第三方存储库是 <strong>RPM Fusion</strong>。</p><p>如果你想在你的 Fedora 桌面环境中播放大多数的音频或视频格式的文件，你应该从 RPM Fusion 中安装必要的多媒体编码器，如下所述。</p><h3 id="在-fedora-linux-中安装多媒体编码器" tabindex="-1">在 Fedora Linux 中安装多媒体编码器 <a class="header-anchor" href="#在-fedora-linux-中安装多媒体编码器" aria-label="Permalink to 在 Fedora Linux 中安装多媒体编码器">​</a></h3><p>确保你已经在你的 Fedora 机器中安装了 RPM Fusion 存储库。如果你尚未添加它，参考下面的链接来在 Fedora 中启用 RPM Fusion 存储库：</p>',10)),s("ul",null,[s("li",null,[l(t,{href:"https://ostechnix.com/how-to-enable-rpm-fusion-repository-in-fedora-rhel/"},{default:n(()=>e[0]||(e[0]=[a("如何在 Fedora、RHEL 中启用 RPM Fusion 存储库")])),_:1})])]),e[23]||(e[23]=i('<p>在启用 RPM Fusion 存储库后，在你的 Fedora 系统中依次运行下面的命令来安装多媒体编码器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install gstreamer1-plugins-{bad-\\*,good-\\*,base} gstreamer1-plugin-openh264 gstreamer1-libav --exclude=gstreamer1-plugins-bad-free-devel</span></span></code></pre></div><p>如果上面的命令不工作，尝试下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install gstreamer1-plugins-{bad-*,good-*,base} gstreamer1-plugin-openh264 gstreamer1-libav --exclude=gstreamer1-plugins-bad-free-devel</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install lame* --exclude=lame-devel</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf group upgrade --with-optional Multimedia</span></span></code></pre></div><p>这三个命令安装了非常多的东西，可以在你的 Fedora 系统中播放所有的音频和视频格式的文件。</p><h4 id="安装多媒体播放器" tabindex="-1">安装多媒体播放器 <a class="header-anchor" href="#安装多媒体播放器" aria-label="Permalink to 安装多媒体播放器">​</a></h4><p>一些流行的媒体播放器，诸如 VLC、Celluloid、SMplayer 和 Plex-media-palyer 等等，将提供所有需要的编码器。你不需要将它们全部都安装，只要任意一两个就足够了。下面给出安装这些播放器的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install vlc</span></span></code></pre></div><p>VLC 预装在很多 Linux 发行版中，它是一个标准的用于播放各种媒体类型文件的媒体播放器。</p><p>SMplayer 是 Mplayer 的前端，它被认为是 VLC 的最佳替代品。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install smplayer</span></span></code></pre></div><p>如果你想要更强大是多媒体体验，安装 Plex-media-player。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install plex-media-player</span></span></code></pre></div>',15)),s("p",null,[e[2]||(e[2]=a("这将不仅为你提供 H264、H265、VP8 和 VP9 编码器（均带硬件支持），它也将启用一种更高效的编码器 AV1（又名 AV01）。你可以使用 ")),l(t,{href:"https://www.youtube.com/playlist?list=PLyqf6gJt7KuHBmeVzZteZUlNUQAVLwrZS"},{default:n(()=>e[1]||(e[1]=[a("AV1 Beta Launch Playlist")])),_:1}),e[3]||(e[3]=a(" 来测试你的浏览器是否支持这个编码器。"))]),e[24]||(e[24]=i('<p>它们中的一些播放器也可以作为 <strong>flatpak</strong> 格式的应用程序来使用。如果与传统的软件包管理器相比，你更喜欢 flatpak 格式的应用程序，你可以安装它们。现在大多数的 Linux 发行版都支持开箱即用的 flatpak 格式的应用程序</p><p>为安装 VLC 的 flatpak 版本，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ flatpak install vlc</span></span></code></pre></div><h4 id="可选-安装-ffmpeg" tabindex="-1">可选 - 安装 FFmpeg <a class="header-anchor" href="#可选-安装-ffmpeg" aria-label="Permalink to 可选 - 安装 FFmpeg">​</a></h4><p><strong>FFmpeg</strong> 是一个功能强大的多媒体框架，它可用于编码、解码、转码、混流、解混流、录制、音轨、过滤等，以及播放各种类型的媒体文件。你可以通过在你的系统上安装 FFmpeg 来获取相应的解码器。</p>',5)),s("ul",null,[s("li",null,[l(t,{href:"https://ostechnix.com/install-ffmpeg-linux/"},{default:n(()=>e[4]||(e[4]=[a("如何在 Linux 中安装 FFmpeg")])),_:1})])]),e[25]||(e[25]=s("p",null,"希望这有帮助。",-1)),e[26]||(e[26]=s("p",null,[s("strong",null,"相关阅读：")],-1)),s("ul",null,[s("li",null,[l(t,{href:"https://ostechnix.com/enable-h264-on-chromium-and-firefox-in-fedora-silverblue/"},{default:n(()=>e[5]||(e[5]=[a("在 Fedora Silverblue 中的 Chromium 和 Firefox 上启用 H264")])),_:1})]),s("li",null,[l(t,{href:"https://ostechnix.com/how-to-install-multimedia-codecs-in-opensuse/"},{default:n(()=>e[6]||(e[6]=[a("如何在 OpenSUSE 中安装多媒体解码器")])),_:1})])]),e[27]||(e[27]=s("hr",null,null,-1)),s("p",null,[e[8]||(e[8]=a("via: ")),l(t,{href:"https://ostechnix.com/how-to-install-multimedia-codecs-in-fedora-linux/"},{default:n(()=>e[7]||(e[7]=[a("https://ostechnix.com/how-to-install-multimedia-codecs-in-fedora-linux/")])),_:1})]),s("p",null,[e[13]||(e[13]=a("作者：")),l(t,{href:"https://ostechnix.com/author/sk/"},{default:n(()=>e[9]||(e[9]=[a("sk")])),_:1}),e[14]||(e[14]=a(" 选题：")),l(t,{href:"https://github.com/lkxed"},{default:n(()=>e[10]||(e[10]=[a("lkxed")])),_:1}),e[15]||(e[15]=a(" 译者：")),l(t,{href:"https://github.com/robsean"},{default:n(()=>e[11]||(e[11]=[a("robsean")])),_:1}),e[16]||(e[16]=a(" 校对：")),l(t,{href:"https://github.com/wxy"},{default:n(()=>e[12]||(e[12]=[a("wxy")])),_:1})]),s("p",null,[e[19]||(e[19]=a("本文由 ")),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>e[17]||(e[17]=[a("LCTT")])),_:1}),e[20]||(e[20]=a(" 原创编译，")),l(t,{href:"https://linux.cn/"},{default:n(()=>e[18]||(e[18]=[a("Linux中国")])),_:1}),e[21]||(e[21]=a(" 荣誉推出"))])])}const F=o(u,[["render",g]]);export{k as __pageData,F as default};
